		@Override
		public long multiplicity() {
			return input.multiplicity();
		}

		@Override
		public FactorEnvironment factors() {
			return input.factors();
		}

		@Override
		public void close() {
			if (!closed) {
				closed = true;
				try {
					release();
				} finally {
					input.close();
				}
			}
		}
